// Package plugin embeds the IDA-side Python plugin and installs it into
// IDA's user plugins directory.
//
// The embedded snapshot is generated by scripts/sync_plugin.py. The Go binary
// is the only artifact users need: `ida-cli install` writes these files into
// the directory IDA loads plugins from. Python itself is still required inside
// IDA (IDA ships it), but no pip package, broker, or MCP server is needed.
package plugin

import (
	"embed"
	"encoding/json"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"strings"
)

//go:embed all:assets
var assets embed.FS

const (
	loaderName  = "ida_mcp.py"
	packageName = "ida_mcp"
	brokerName  = "broker"
)

// Manifest describes the embedded plugin snapshot.
type Manifest struct {
	Source      string `json:"source"`
	Commit      string `json:"commit"`
	GeneratedAt string `json:"generated_at"`
	Files       int    `json:"files"`
	Note        string `json:"note"`
}

// Status reports whether the plugin is installed in a plugins directory.
type Status struct {
	Dir       string
	Installed bool
	Missing   []string
	Manifest  Manifest
}

// InstallResult is returned by Install.
type InstallResult struct {
	Dir      string
	Files    int
	Loader   string
	Manifest Manifest
}

// ReadManifest returns provenance for the embedded snapshot.
func ReadManifest() (Manifest, error) {
	var manifest Manifest
	raw, err := assets.ReadFile("assets/manifest.json")
	if err != nil {
		return manifest, err
	}
	if err := json.Unmarshal(raw, &manifest); err != nil {
		return manifest, err
	}
	return manifest, nil
}

// DefaultPluginsDir returns IDA's user plugins directory.
//
//	Windows: %APPDATA%\Hex-Rays\IDA Pro\plugins
//	other:   ~/.idapro/plugins
//
// IDAUSR overrides the user directory when set.
func DefaultPluginsDir() (string, error) {
	if userDir := os.Getenv("IDAUSR"); userDir != "" {
		return filepath.Join(userDir, "plugins"), nil
	}
	if runtime.GOOS == "windows" {
		appData := os.Getenv("APPDATA")
		if appData == "" {
			if dir, err := os.UserConfigDir(); err == nil {
				appData = dir
			}
		}
		if appData == "" {
			return "", fmt.Errorf("APPDATA is not set; pass --dir")
		}
		return filepath.Join(appData, "Hex-Rays", "IDA Pro", "plugins"), nil
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, ".idapro", "plugins"), nil
}

// HasIDAFreeLicense reports whether the IDA user directory contains an IDA
// Free license file. IDA Free does not load plugins.
func HasIDAFreeLicense(userDir string) bool {
	matches, _ := filepath.Glob(filepath.Join(userDir, "idafree_*.hexlic"))
	return len(matches) > 0
}

// Check inspects one plugins directory.
func Check(dir string) Status {
	status := Status{Dir: dir}
	required := []string{
		filepath.Join(dir, loaderName),
		filepath.Join(dir, packageName, "__init__.py"),
		filepath.Join(dir, brokerName, "__init__.py"),
		filepath.Join(dir, brokerName, "cache_handlers.py"),
	}
	for _, path := range required {
		if _, err := os.Stat(path); err != nil {
			status.Missing = append(status.Missing, path)
		}
	}
	status.Installed = len(status.Missing) == 0
	status.Manifest, _ = ReadManifest()
	return status
}

// Install replaces ida_mcp.py, ida_mcp/ and broker/ in dir with the embedded
// snapshot. Unrelated files in the plugins directory are left alone.
func Install(dir string) (InstallResult, error) {
	result := InstallResult{Dir: dir}
	if strings.TrimSpace(dir) == "" {
		return result, fmt.Errorf("plugins directory is empty")
	}
	result.Manifest, _ = ReadManifest()
	result.Loader = filepath.Join(dir, loaderName)

	if err := os.MkdirAll(dir, 0o755); err != nil {
		return result, fmt.Errorf("create plugins directory: %w", err)
	}
	for _, name := range []string{loaderName, packageName, brokerName} {
		if err := removePath(filepath.Join(dir, name)); err != nil {
			return result, fmt.Errorf("remove old %s: %w", name, err)
		}
	}

	err := fs.WalkDir(assets, "assets", func(path string, entry fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		rel := strings.TrimPrefix(path, "assets/")
		if rel == "" || rel == "assets" || rel == "manifest.json" {
			return nil
		}
		target := filepath.Join(dir, filepath.FromSlash(rel))
		if entry.IsDir() {
			return os.MkdirAll(target, 0o755)
		}
		data, err := assets.ReadFile(path)
		if err != nil {
			return err
		}
		if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
			return err
		}
		if err := os.WriteFile(target, data, 0o644); err != nil {
			return err
		}
		result.Files++
		return nil
	})
	if err != nil {
		return result, fmt.Errorf("write plugin files: %w", err)
	}
	return result, nil
}

// Uninstall removes the loader and the two package directories. It returns the
// paths that were removed.
func Uninstall(dir string) ([]string, error) {
	var removed []string
	for _, name := range []string{loaderName, packageName, brokerName} {
		path := filepath.Join(dir, name)
		if _, err := os.Lstat(path); err != nil {
			if os.IsNotExist(err) {
				continue
			}
			return removed, err
		}
		if err := removePath(path); err != nil {
			return removed, fmt.Errorf("remove %s: %w", path, err)
		}
		removed = append(removed, path)
	}
	sort.Strings(removed)
	return removed, nil
}

// removePath removes files, directories, and symlinks without following a
// symlink into the source tree (upstream `ida-pro-mcp --install` may have
// created symlinks into the Python package).
func removePath(path string) error {
	info, err := os.Lstat(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return os.Remove(path)
	}
	return os.RemoveAll(path)
}
